package com.vandorlabs.neoforge.canopy;

import com.google.gson.*;
import com.vandorlabs.persistence.CanopySettingsData;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.Blocks;

/** Replays actual released apply/reshape transactions in a registered ServerLevel. */
final class CanopyConfigurationHostChecks {
    private static long checks;private static String context;
    private static void need(boolean yes,String text){checks++;if(!yes)throw new AssertionError("Canopy configuration "+context+" "+text);}
    private static BlockPos point(JsonArray p){return new BlockPos(p.get(0).getAsInt(),p.get(1).getAsInt(),p.get(2).getAsInt());}
    private static final BlockPos ROOT=new BlockPos(8,80,8);
    private static CompoundTag own(String text){var p=text.split(":");var tag=new CompoundTag();String[] keys={"Depth","Scale","Shade","Tint","Mount","Motion","Hinge","Angle","Material","TextureLayout"};for(int i=0;i<keys.length;i++)tag.putInt("Canopy"+keys[i],Integer.parseInt(p[i]));String[] bools={"SlideForward","Openable","Redstone","ActivateOnPower"};for(int i=0;i<bools.length;i++)tag.putBoolean("Canopy"+bools[i],Boolean.parseBoolean(p[10+i]));tag.putBoolean("CanopyTileMaterial",Integer.parseInt(p[9])==1);tag.putIntArray("CanopyChannels",new int[0]);if(!p[14].equals("0")){var values=p[14].split(",");int[] channels=new int[values.length];for(int i=0;i<values.length;i++)channels[i]=Integer.parseInt(values[i].trim());tag.putIntArray("CanopyChannels",channels);}return tag;}
    private static NativeCanopySettings requested(CompoundTag tag){var a=NativeCanopySettings.read(tag).data();return new NativeCanopySettings(new CanopySettingsData(tag.getInt("CanopyDepth"),tag.getInt("CanopyScale"),tag.getInt("CanopyShade"),tag.getInt("CanopyTint"),a.mount,a.motion,a.hinge,a.angle,a.material,a.openable,a.redstone,a.slideForward,a.tileMaterial,a.activateOnPower,a.textureLayout(),a.channels));}
    private static NativeCanopySettings shade(NativeCanopyEntity owner){var tag=new CompoundTag();owner.settings().write(tag);tag.putInt("CanopyShade",2);return NativeCanopySettings.read(tag);}
    private static void guards(ServerLevel world){context="independent installed authorization and identity";var pos=new BlockPos(104,238,104);world.getChunkAt(pos);var opaque=new CompoundTag();opaque.putString("PrivateCanopyEnvelope","unchanged");var platform=new CompoundTag();platform.putLong("PrivatePlatformValue",173L);opaque.put("NeoForgeData",platform);var owner=CanopyHostChecks.put(world,pos,"angled_front_1x1",Direction.SOUTH,opaque);var before=owner.saveWithoutMetadata(world.registryAccess());var next=shade(owner);need(!java.util.concurrent.CompletableFuture.supplyAsync(()->NativeCanopyConfiguration.apply(owner,null,next)).join(),"worker configuration refused before discovery");
        var player=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(java.util.UUID.fromString("8f62a22a-3cf5-47b7-814b-acd3e97e383d"),"CanopyConfig"));player.setGameMode(net.minecraft.world.level.GameType.SPECTATOR);need(!NativeCanopyConfiguration.apply(owner,player,next),"spectator refused");need(!NativeCanopyConfiguration.apply(owner,null,next,new NativeCanopyConfiguration.Access(){@Override public boolean editable(NativeCanopyEntity o,net.minecraft.world.entity.player.Player p,BlockPos cell){return false;}}),"edit denial");need(before.equals(owner.saveWithoutMetadata(world.registryAccess())),"all refused paths retain exact private envelope");need(NativeCanopyConfiguration.apply(owner,null,next),"valid installed appearance edit");var after=owner.saveWithoutMetadata(world.registryAccess());need(after.getString("PrivateCanopyEnvelope").equals("unchanged")&&after.getCompound("NeoForgeData").equals(platform),"successful settings edit preserves platform/private fields");
        need(!NativeCanopyConfiguration.apply(owner,null,next,new NativeCanopyConfiguration.Access(){@Override public boolean loaded(NativeCanopyEntity o,BlockPos cell){return false;}@Override public net.minecraft.world.level.block.state.BlockState state(NativeCanopyEntity o,BlockPos cell){throw new AssertionError("Cold configuration discovery");}}),"cold view refuses without state discovery");var pairTag=opaque.copy();pairTag.putLong("Pair",com.vandorlabs.persistence.LegacyBlockPosition.pack(pos.getX(),pos.getY(),pos.getZ()));pairTag.putInt("CanopyWidth",2);owner.loadWithComponents(pairTag,world.registryAccess());need(!NativeCanopyConfiguration.apply(owner,null,next),"incomplete joined column does not partially configure");owner.loadWithComponents(opaque,world.registryAccess());var stale=owner;world.removeBlockEntity(pos);var fresh=(NativeCanopyEntity)CanopyHostChecks.block("angled_front_1x1").newBlockEntity(pos,owner.getBlockState());fresh.loadWithComponents(opaque,world.registryAccess());world.setBlockEntity(fresh);need(!NativeCanopyConfiguration.apply(stale,null,next)&&NativeCanopyLifecycle.at(world,pos)==fresh,"stale owner cannot configure replacement");
        for(var cell:BlockPos.betweenClosed(pos.offset(-8,-8,-8),pos.offset(8,8,8)))world.setBlock(cell,Blocks.AIR.defaultBlockState(),18);var tag=opaque.copy();tag.putBoolean("CenteredPlacement",true);tag.putBoolean("HollowPlacement",true);tag.putLong("Anchor",com.vandorlabs.persistence.LegacyBlockPosition.pack(pos.getX(),pos.getY(),pos.getZ()));var front=CanopyHostChecks.put(world,pos,"front_canopy_glass",Direction.SOUTH,tag);var cells=NativeCanopyFootprint.cells(front.kind(),pos,front.facing(),front.settings(),front.links());front.configurationFootprint(cells);for(var cell:cells)if(!cell.equals(pos)){var helper=CanopyHostChecks.put(world,cell,front.kind(),front.facing(),new CompoundTag());helper.helperOf(front);}var requested=new CompoundTag();front.settings().write(requested);requested.putInt("CanopyDepth",80);requested.putInt("CanopyScale",100);var foreign=new java.util.concurrent.atomic.AtomicReference<NativeCanopyEntity>();var foreignPos=new java.util.concurrent.atomic.AtomicReference<BlockPos>();
        var replacing=new NativeCanopyConfiguration.Access(){@Override public boolean write(NativeCanopyEntity o,BlockPos cell,net.minecraft.world.level.block.state.BlockState state){boolean addition=state.getBlock() instanceof NativeCanopyBlock&&!world.getBlockState(cell).is(state.getBlock());boolean result=NativeCanopyConfiguration.Access.super.write(o,cell,state);if(addition&&foreign.get()==null){world.removeBlockEntity(cell);var replacement=(NativeCanopyEntity)((NativeCanopyBlock)state.getBlock()).newBlockEntity(cell,state);var data=new CompoundTag();data.putString("ForeignOwnerIdentity","preserved");replacement.loadWithComponents(data,world.registryAccess());world.setBlockEntity(replacement);foreign.set(replacement);foreignPos.set(cell);}return result;}};
        need(!NativeCanopyConfiguration.apply(front,null,NativeCanopySettings.read(requested),replacing),"reentrant same-block replacement refuses configuration");need(foreign.get()!=null&&NativeCanopyLifecycle.at(world,foreignPos.get())==foreign.get(),"rollback preserves foreign BE identity");need(foreign.get().saveWithoutMetadata(world.registryAccess()).getString("ForeignOwnerIdentity").equals("preserved")&&!foreign.get().inert(),"rollback does not rewrite foreign saved fields");need(front.inert()&&front.recoverySnapshot().getCompound(NativeCanopyEntity.RECOVERY).getString("PrivateCanopyEnvelope").equals("unchanged"),"unrestored transaction retains original private owner");
        for(var cell:BlockPos.betweenClosed(pos.offset(-8,-8,-8),pos.offset(8,8,8)))world.setBlock(cell,Blocks.AIR.defaultBlockState(),18);
    }
    static void run(ServerLevel world)throws Exception{
        for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)world.getChunk(x,z);
        for(var pos:BlockPos.betweenClosed(ROOT.offset(-12,-12,-12),ROOT.offset(12,12,12)))world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);
        var installed=new HashSet<BlockPos>();int profiles=0,applied=0,faults=0;
        try(var reader=java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(System.getenv("VANDOR_CANOPY_APPLY_REFERENCE")))){for(String line;(line=reader.readLine())!=null;){var row=JsonParser.parseString(line).getAsJsonObject();context=row.get("id")+"/"+profiles+"/"+row.get("profile");for(var pos:installed)world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);installed.clear();String kind=row.get("id").getAsString();var facing=Direction.from3DDataValue(row.get("facing").getAsInt());var before=row.getAsJsonObject("before");var rootSaved=CanopySettingsChecks.tags(before.getAsJsonObject("saved"));int columns=row.get("columns").getAsInt();
            for(var raw:before.getAsJsonArray("members")){var member=raw.getAsJsonObject();var pos=point(member.getAsJsonArray("pos"));installed.add(pos);if(member.get("id").getAsString().equals("minecraft:stone")){world.setBlock(pos,Blocks.STONE.defaultBlockState(),18);continue;}var tag=own(member.get("settings").getAsString());var anchor=point(member.getAsJsonArray("anchor"));tag.putLong("Anchor",com.vandorlabs.persistence.LegacyBlockPosition.pack(anchor.getX(),anchor.getY(),anchor.getZ()));tag.putBoolean("CenteredPlacement",member.get("centered").getAsBoolean());tag.putBoolean("HollowPlacement",member.get("hollow").getAsBoolean());if(pos.equals(anchor)&&columns>1){tag.putLong("Pair",com.vandorlabs.persistence.LegacyBlockPosition.pack(ROOT.getX(),ROOT.getY(),ROOT.getZ()));tag.putInt("CanopyWidth",columns);}if(pos.equals(ROOT))tag=rootSaved.copy();CanopyHostChecks.put(world,pos,kind,facing,tag);}
            var owner=NativeCanopyLifecycle.at(world,ROOT);var next=requested(CanopySettingsChecks.tags(row.getAsJsonObject("request")));int profile=row.get("profile").getAsInt();var denied=profile==23||profile==19&&!CanopySettingsData.supports(kind)?ROOT:null;
            var access=new NativeCanopyConfiguration.Access(){int writes,removals;boolean triggered;
                @Override public boolean editable(NativeCanopyEntity owner,net.minecraft.world.entity.player.Player player,BlockPos pos){return !pos.equals(denied)&&loaded(owner,pos);}
                @Override public boolean write(NativeCanopyEntity owner,BlockPos pos,net.minecraft.world.level.block.state.BlockState state){boolean addition=state.getBlock() instanceof NativeCanopyBlock&&!world.getBlockState(pos).is(state.getBlock());if(addition&&++writes==2&&profile==20){triggered=true;return false;}if(state.isAir()&&world.getBlockState(pos).getBlock() instanceof NativeCanopyBlock&&++removals==2&&profile==22){triggered=true;return false;}boolean result=NativeCanopyConfiguration.Access.super.write(owner,pos,state);installed.add(pos);if(addition&&writes==2&&profile==21){triggered=true;world.removeBlockEntity(pos);}return result;}
            };
            boolean result=NativeCanopyConfiguration.apply(owner,null,next,access);need(result==row.get("applied").getAsBoolean(),"accepted expected="+row.get("applied")+" actual="+result);need(access.triggered==row.get("faultTriggered").getAsBoolean(),"fault path");if(result)applied++;if(access.triggered)faults++;
            var after=row.getAsJsonObject("after");var expectedCells=after.getAsJsonArray("footprint");var actualCells=NativeCanopyFootprint.cells(kind,ROOT,facing,owner.settings(),owner.links());need(expectedCells.size()==actualCells.size(),"footprint size");for(int i=0;i<expectedCells.size();i++)need(actualCells.get(i).equals(point(expectedCells.get(i).getAsJsonArray())),"ordered footprint");
            var expectedPositions=new HashSet<BlockPos>();for(var raw:after.getAsJsonArray("members")){var expected=raw.getAsJsonObject();var pos=point(expected.getAsJsonArray("pos"));expectedPositions.add(pos);if(expected.get("id").getAsString().equals("minecraft:stone")){need(world.getBlockState(pos).is(Blocks.STONE),"foreign stone preserved");continue;}var member=NativeCanopyLifecycle.at(world,pos);need(member!=null,"member exists "+pos);var settings=new CompoundTag();member.settings().write(settings);need(settings.equals(own(expected.get("settings").getAsString())),"member settings "+pos+" expected="+own(expected.get("settings").getAsString())+" actual="+settings);need(member.links().anchor().equals(point(expected.getAsJsonArray("anchor"))),"anchor");need(NativeCanopyLifecycle.owner(member).getBlockPos().equals(point(expected.getAsJsonArray("owner"))),"owner");need(member.links().centered()==expected.get("centered").getAsBoolean()&&member.links().hollow()==expected.get("hollow").getAsBoolean(),"placement flags");need(member.publication().draws()==expected.get("draws").getAsBoolean(),"draw ownership");}
            for(var pos:installed)need(expectedPositions.contains(pos)||world.getBlockState(pos).isAir(),"no extra surviving cells "+pos);profiles++;
        }}for(var pos:installed)world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);guards(world);need(profiles==7584&&applied==3652&&faults==672,"corpus coverage "+profiles+"/"+applied+"/"+faults);System.out.println("[vandorlabs][canopy-config-host] PASS profiles="+profiles+" applied="+applied+" faults="+faults+" checks="+checks);
    }
}
